class Solution {
public:
    int waysToSplit(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
        int total = pref[n];
        long long ans = 0;

        for (int i = 1; i <= n - 2; ++i) {
            int left_sum = pref[i];
            if (left_sum * 3 > total) break;
            auto low = lower_bound(pref.begin() + i + 1, pref.begin() + n, 2 * left_sum);
            auto high = upper_bound(pref.begin() + i + 1, pref.begin() + n, (total + left_sum) / 2) - 1;
            if (low <= high) {
                ans = (ans + (high - low + 1)) % MOD;
            }
        }
        return ans;
    }
};

class Solution {
    public int waysToSplit(int[] nums) {
        final int MOD = 1_000_000_007;
        int n = nums.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
        int total = pref[n];
        long ans = 0;

        for (int i = 1; i <= n - 2; ++i) {
            int leftSum = pref[i];
            if (leftSum * 3 > total) break;

            int low = i + 1, high = n - 1, minJ = -1;
            while (low <= high) {
                int mid = (low + high) / 2;
                if (pref[mid] >= 2 * leftSum) {
                    minJ = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }

            low = i + 1; high = n - 1; int maxJ = -1;
            while (low <= high) {
                int mid = (low + high) / 2;
                if (pref[mid] <= (total + leftSum) / 2) {
                    maxJ = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            if (minJ != -1 && maxJ != -1 && minJ <= maxJ) {
                ans = (ans + (maxJ - minJ + 1)) % MOD;
            }
        }
        return (int)ans;
    }
}

